-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "eDP-1",
    mode     = "1920x1080@144",
    position = "0x0",
    scale    = 1,
})
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal    = "kitty"
local fileManager = "dolphin"
local menu        = "rofi -show drun"


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
hl.on("hyprland.start", function ()
  hl.exec_cmd("waybar")
  hl.exec_cmd("swaync")  -- notis + centro de control
  hl.exec_cmd("nm-applet --indicator")
  hl.exec_cmd("blueman-applet")
  hl.exec_cmd("systemctl --user start hyprpolkitagent hyprpaper hypridle")
  hl.exec_cmd("wl-paste --watch cliphist store")
  hl.exec_cmd("~/.config/hypr/scripts/mute-watch.py")  -- detective del mute (log en ~/.cache/angel-mute.log)
  hl.exec_cmd("hyprpm reload -n")  -- carga plugins (hyprbars)
  hl.exec_cmd("command -v pcmanfm-qt >/dev/null && pcmanfm-qt --desktop --profile=default")  -- íconos del escritorio
  hl.exec_cmd("~/.config/hypr/scripts/sounds.py")                 -- 🔔 pop al cambiar de escritorio
  hl.exec_cmd("sleep 2; pw-play --volume 0.7 ~/.local/share/sounds/angel/login.ogg")  -- 🎶 sonidito de bienvenida
  hl.exec_cmd("~/.config/hypr/scripts/battery-watch.sh")          -- avisos de batería baja
  hl.exec_cmd("python3 ~/.config/hypr/widgets/angel-music.py")     -- widget de música (escritorio)
  hl.exec_cmd("python3 ~/.config/hypr/widgets/angel-desk.py")      -- widgets: reloj, clima, clases, etc.
  hl.exec_cmd("python3 ~/.config/hypr/widgets/angel-pet.py")       -- mascota angelito
  hl.exec_cmd("hyprctl setcursor Angel-Cursor 24")
  hl.exec_cmd("gsettings set org.gnome.desktop.interface cursor-theme Angel-Cursor")
  hl.exec_cmd("gsettings set org.gnome.desktop.interface font-name 'Noto Sans 10'")
end)


