---------------------
---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + C", hl.dsp.window.close())
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'"))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))    -- dwindle only

-- Extras
hl.bind(mainMod .. " + L",         hl.dsp.exec_cmd("hyprlock"))
hl.bind(mainMod .. " + B",         hl.dsp.exec_cmd("firefox"))
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("~/.config/hypr/scripts/clip.sh"))   -- historial del portapapeles
hl.bind(mainMod .. " + W",         hl.dsp.exec_cmd("~/.config/hypr/scripts/wall.sh"))   -- selector de wallpapers
hl.bind(mainMod .. " + period",    hl.dsp.exec_cmd("pkill -x rofi || ~/.config/hypr/scripts/kaomoji.sh"))  -- (˘ω˘) kaomojis
hl.bind(mainMod .. " + SHIFT + A", hl.dsp.exec_cmd("~/.config/angel-theme/theme.py toggle"))  -- ☾ modo Ame / ♡ modo Angel
hl.bind(mainMod .. " + G",         hl.dsp.exec_cmd("~/.config/hypr/scripts/showcase.sh"))  -- ✨ modo showcase on/off
hl.bind(mainMod .. " + Tab",       hl.dsp.exec_cmd("pkill -x rofi || ~/.config/hypr/scripts/overview.sh"))  -- 🪟 vista general
hl.bind(mainMod .. " + SHIFT + D", hl.dsp.exec_cmd("pkill -f widgets/angel-desk.py || python3 ~/.config/hypr/widgets/angel-desk.py"))  -- widgets on/off
hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd("pkill -f widgets/angel-pet.py || python3 ~/.config/hypr/widgets/angel-pet.py"))  -- mascota on/off
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.exec_cmd("~/.config/hypr/scripts/cc.sh night"))  -- luz nocturna on/off
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd("hyprpicker -a -f hex && notify-send '🎨 color copiado' \"$(wl-paste)\""))  -- gotero de color
-- 📸 capturas (con notificación cute)
hl.bind("Print",                   hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh shot-area"))
hl.bind("SHIFT + Print",           hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh shot-full"))
hl.bind(mainMod .. " + SHIFT + Print", hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh shot-edit"))
-- 🌸 extras
hl.bind(mainMod .. " + A",         hl.dsp.exec_cmd("swaync-client -t -sw"))  -- centro de control
hl.bind(mainMod .. " + X",         hl.dsp.exec_cmd("pkill wlogout || wlogout -b 5 -T 380 -B 380"))
hl.bind(mainMod .. " + F",         hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ action = "toggle" }))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh bar-reload"))
hl.bind(mainMod .. " + slash",     hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh keys"))

-- 🪽 minimizar (Hyprland no minimiza de verdad: se van al workspace especial "minimized")
hl.bind(mainMod .. " + H",         hl.dsp.exec_cmd("~/.config/hypr/scripts/minimize.sh hide"))     -- minimizar
hl.bind(mainMod .. " + SHIFT + H", hl.dsp.exec_cmd("~/.config/hypr/scripts/minimize.sh restore"))  -- regresar una
hl.bind(mainMod .. " + D",         hl.dsp.exec_cmd("~/.config/hypr/scripts/minimize.sh desktop"))  -- ver escritorio
hl.bind(mainMod .. " + N", hl.dsp.workspace.toggle_special("minimized"))                           -- ver minimizadas

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }))

-- 🪽 mover la ventana activa con SUPER + SHIFT + flechas
for _, dir in ipairs({ "left", "right", "up", "down" }) do
    hl.bind(mainMod .. " + SHIFT + " .. dir, hl.dsp.window.move({ direction = dir }))
end

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh vol-up"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh vol-down"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh vol-mute"),     { locked = true })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),   { locked = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh bri-up"),                  { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("~/.config/hypr/scripts/angel.sh bri-down"),                  { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })


--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------

-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- 🪟 ventanitas flotantes para utilidades
for _, cls in ipairs({ "pavucontrol", "org.pulseaudio.pavucontrol", "blueman-manager", "nm-connection-editor",
                       "nwg-look", "qt6ct", "swappy", "xdg-desktop-portal-gtk", "org.kde.ark",
                       "floating-gdu", "floating-nmtui" }) do
    hl.window_rule({
        name   = "float-" .. cls,
        match  = { class = "^(" .. cls:gsub("%.", "\\.") .. ")$" },
        float  = true,
        center = true,
        size   = "900 600",
    })
end
hl.window_rule({
    name  = "float-dialogs",
    match = { title = "^(Open File|Save File|Open Folder|Abrir archivo|Guardar archivo|Picture-in-Picture)(.*)$" },
    float = true,
})
hl.window_rule({
    name  = "pip-pin",
    match = { title = "^(Picture-in-Picture)$" },
    pin   = true,
})

-- ✨ blur detrás de la barra, el menú, las notis y el logout
for _, ns in ipairs({ "waybar", "top", "dock", "rofi", "notifications", "logout_dialog", "swaync-control-center", "swaync-notification-window" }) do
    hl.layer_rule({
        name         = "blur-" .. ns,
        match        = { namespace = "^(" .. ns .. ")$" },
        blur         = true,
        ignore_alpha = 0.3,
    })
end

-- 🎀 rofi y el logout aparecen con pop-in
for _, ns in ipairs({ "rofi", "logout_dialog" }) do
    hl.layer_rule({
        name      = "anim-" .. ns,
        match     = { namespace = "^(" .. ns .. ")$" },
        animation = "popin 80%",
    })
end

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})


